import java.util.*;
public class EqualsOnlyHashMapDemo {
  public static void main(String[] args) {
    class Key { final String id; Key(String id){this.id=id;} public boolean equals(Object o){return o instanceof Key k && id.equals(k.id);} }
    var a=new Key("GCP1"); var b=new Key("GCP1"); var m=new java.util.HashMap<Key,String>(); m.put(a,"survey"); System.out.println(a.equals(b)+" "+m.containsKey(b));
  }
}
